import json
import pickle
from typing import List

import pandas as pd
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

FEATURES = ['MedInc', 'HouseAge', 'AveRooms', 'AveBedrms', 'Population', 'AveOccup', 'Latitude', 'Longitude']
MODEL_PATH = '/app/models/best_model.pkl'
COMPARISON_PATH = '/app/output/model_comparison.json'

with open(MODEL_PATH, 'rb') as f:
    model = pickle.load(f)
with open(COMPARISON_PATH) as f:
    MODEL_NAME = json.load(f)['best_model_name']
MODEL_TYPE = type(model).__name__

app = FastAPI(title='California Housing Price Prediction')


class PredictRequest(BaseModel):
    features: List[float]


class BatchPredictRequest(BaseModel):
    features_list: List[List[float]]


def to_frame(rows):
    for r in rows:
        if len(r) != len(FEATURES):
            raise HTTPException(status_code=422, detail='Each sample must have exactly 8 features')
    return pd.DataFrame(rows, columns=FEATURES)


@app.get('/health')
def health():
    return {'status': 'healthy', 'model_loaded': model is not None}


@app.get('/model-info')
def model_info():
    return {'model_name': MODEL_NAME, 'model_type': MODEL_TYPE, 'features_count': len(FEATURES)}


@app.post('/predict')
def predict(req: PredictRequest):
    X = to_frame([req.features])
    pred = model.predict(X)
    return {'prediction': float(pred[0]), 'model_name': MODEL_NAME}


@app.post('/predict-batch')
def predict_batch(req: BatchPredictRequest):
    X = to_frame(req.features_list)
    preds = model.predict(X)
    return {'predictions': [float(p) for p in preds], 'model_name': MODEL_NAME, 'count': len(preds)}
EOF
